using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using OnlyWorkspace.Core.Archive;

namespace OnlyWorkspace.Tests.Fidelity;

// Test-only contracts. Expected facts are hand-authored, never generated by the extractor.
public sealed class FidelityCorpus
{
    public int Version { get; set; }
    public List<FidelityCase> Cases { get; set; } = new();
    public List<FidelityScenario> Scenarios { get; set; } = new();
}
public sealed class FidelityCase
{
    public string Id { get; set; } = "";
    public string Language { get; set; } = "";
    public List<string> Tags { get; set; } = new();
    public string Thread { get; set; } = "";
    public string Subject { get; set; } = "";
    public string Sender { get; set; } = "";
    public DateTime ReceivedUtc { get; set; }
    public List<FidelitySource> Sources { get; set; } = new();
    public List<string> Review { get; set; } = new();
}
public sealed class FidelitySource
{
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
    public string Text { get; set; } = "";
    public List<FidelityClaim> Expected { get; set; } = new();
}
public sealed class FidelityScenario
{
    public string Id { get; set; } = "";
    public List<string> CaseIds { get; set; } = new();
    public string Goal { get; set; } = "";
    public List<string> Review { get; set; } = new();
    public List<FidelityClaim> Expected { get; set; } = new();
}
public sealed class FidelityClaim
{
    public ArchiveFactKind Kind { get; set; }
    public string Raw { get; set; } = "";
    public string? Value { get; set; }
    public string? Currency { get; set; }
    public int Occurrence { get; set; }
    public string CaseId { get; set; } = "";
    public string SourceId { get; set; } = "";
    public int Start { get; set; }
    public int Length { get; set; }
    public bool ContextOnly { get; set; }
}
public sealed class FidelityMetric
{
    public int TP { get; set; }
    public int FP { get; set; }
    public int FN { get; set; }
    public int Duplicates { get; set; }
    public int WrongSource { get; set; }
    public double? Precision => TP + FP == 0 ? null : (double)TP / (TP + FP);
    public double? Recall => TP + FN == 0 ? null : (double)TP / (TP + FN);
}
public static class FidelityBench
{
    public static void WriteOffline(string corpusPath, string outputDirectory)
    {
        var corpus = Load(corpusPath);
        Directory.CreateDirectory(outputDirectory);
        File.WriteAllText(Path.Combine(outputDirectory, "offline.json"), JsonSerializer.Serialize(Offline(corpus), Json));
    }
    public static readonly JsonSerializerOptions Json = new()
    {
        WriteIndented = true, PropertyNameCaseInsensitive = true,
        Converters = { new JsonStringEnumConverter() }
    };
    public static string Hash(string text)
    {
        using var sha = SHA256.Create(); return string.Concat(sha.ComputeHash(Encoding.UTF8.GetBytes(text)).Select(b => b.ToString("x2")));
    }
    public static FidelityCorpus Load(string path)
    {
        var corpus = JsonSerializer.Deserialize<FidelityCorpus>(File.ReadAllText(path), Json) ?? throw new InvalidDataException("Missing corpus");
        if (corpus.Version != 1 || corpus.Cases.Count == 0 || corpus.Cases.Select(c => c.Id).Distinct().Count() != corpus.Cases.Count)
            throw new InvalidDataException("Invalid corpus version or case identifiers");
        foreach (var c in corpus.Cases)
        {
            if (c.Language is not ("it" or "en") || c.Sources.Count == 0 || c.Review.Count == 0 ||
                c.Sources.Select(s => s.Id).Distinct().Count() != c.Sources.Count) throw new InvalidDataException("Invalid case " + c.Id);
            foreach (var s in c.Sources)
                foreach (var f in s.Expected)
                {
                    if (f.Raw.Length == 0 || f.Occurrence < 0) throw new InvalidDataException("Missing expected source span");
                    int start = -1;
                    for (int n = 0; n <= f.Occurrence; n++)
                    {
                        start = s.Text.IndexOf(f.Raw, start + 1, StringComparison.Ordinal);
                        if (start < 0) throw new InvalidDataException("Expected span absent: " + c.Id + "/" + f.Raw);
                    }
                    f.CaseId = c.Id; f.SourceId = s.Id; f.Start = start; f.Length = f.Raw.Length;
                }
        }
        if (corpus.Scenarios.Select(s => s.Id).Distinct().Count() != corpus.Scenarios.Count ||
            corpus.Scenarios.Any(s => s.CaseIds.Count == 0 || s.Review.Count == 0 || s.CaseIds.Any(id => !corpus.Cases.Any(c => c.Id == id))))
            throw new InvalidDataException("Invalid scenarios");
        foreach (var scenario in corpus.Scenarios)
            if (scenario.Expected.Count == 0 || scenario.Expected.Any(f => !corpus.Cases.Where(c => scenario.CaseIds.Contains(c.Id) && c.Id == f.CaseId)
                .SelectMany(c => c.Sources.Where(s => s.Id == f.SourceId).SelectMany(s => s.Expected))
                .Any(e => e.Kind == f.Kind && e.Value == f.Value && e.Currency == f.Currency && e.Raw == f.Raw)))
                throw new InvalidDataException("Scenario expectations must reference annotated source facts");
        return corpus;
    }
    public static Dictionary<string, string> Sources(IEnumerable<FidelityCase> cases) => cases.SelectMany(c => c.Sources.Select(s =>
        new KeyValuePair<string, string>(c.Id + "/" + s.Id, Hash(s.Text)))).ToDictionary(p => p.Key, p => p.Value);

    public static List<FidelityClaim> Extract(FidelityCase c) => c.Sources.SelectMany(s => ArchiveFactExtractor.Extract(s.Text, s.Id, s.Name).Select(f =>
        new FidelityClaim { CaseId = c.Id, SourceId = s.Id, Kind = f.Kind, Raw = f.Raw, Value = f.Value, Currency = f.Currency, Start = f.Start, Length = f.Length })).ToList();

    public static Dictionary<string, FidelityMetric> Score(IEnumerable<FidelityClaim> expected, IEnumerable<FidelityClaim> observed, bool exactSpans)
    {
        var wanted = expected.ToList(); var actual = observed.ToList(); var matched = new HashSet<int>();
        var metrics = wanted.Concat(actual).Select(f => f.Kind.ToString()).Distinct().OrderBy(k => k, StringComparer.Ordinal)
            .ToDictionary(k => k, _ => new FidelityMetric());
        bool Value(FidelityClaim a, FidelityClaim b) => a.Kind == b.Kind && a.Value == b.Value && a.Currency == b.Currency;
        bool Source(FidelityClaim a, FidelityClaim b) => a.CaseId == b.CaseId && a.SourceId == b.SourceId &&
            (!exactSpans || (a.Start == b.Start && a.Length == b.Length && a.Raw == b.Raw));
        foreach (var f in actual)
        {
            var metric = metrics[f.Kind.ToString()];
            int index = wanted.FindIndex(w => Value(w, f) && Source(w, f) && !matched.Contains(wanted.IndexOf(w)));
            if (index >= 0) { matched.Add(index); metric.TP++; }
            else
            {
                metric.FP++;
                if (wanted.Any(w => Value(w, f) && Source(w, f))) metric.Duplicates++;
                else if (wanted.Any(w => Value(w, f))) metric.WrongSource++;
            }
        }
        for (int i = 0; i < wanted.Count; i++) if (!matched.Contains(i)) metrics[wanted[i].Kind.ToString()].FN++;
        return metrics;
    }

    public static object Offline(FidelityCorpus corpus) => new
    {
        ExtractorRevision = ArchiveFactExtractor.Revision,
        Metrics = Score(corpus.Cases.SelectMany(c => c.Sources.SelectMany(s => s.Expected)), corpus.Cases.SelectMany(Extract), true),
        Cases = corpus.Cases.Select(c => new { c.Id, SourceHashes = Sources(new[] { c }), Expected = c.Sources.SelectMany(s => s.Expected),
            Observed = Extract(c), Metrics = Score(c.Sources.SelectMany(s => s.Expected), Extract(c), true) }).ToList()
    };

}
